// Numéro de la première version de l'agent à analyser (1 = tous les appels)
const VERSION_MIN = 1;

const calls = $input.all()
  .map(i => i.json)
  .filter(c => c.transcript && c.transcript.trim().length > 0)
  .filter(c => (c.agent_version || VERSION_MIN) >= VERSION_MIN);

return calls.map(c => ({ json: {
  call_id: c.call_id,
  date: new Date(c.start_timestamp).toISOString(),
  duree_s: Math.round((c.duration_ms || 0) / 1000),
  fin: c.disconnection_reason || 'inconnu',
  sentiment: (c.call_analysis && c.call_analysis.user_sentiment) || 'inconnu',
  type_appel: (c.call_analysis && c.call_analysis.custom_analysis_data && c.call_analysis.custom_analysis_data.type_appel) || 'inconnu',
  canal: c.call_type || 'inconnu',
  transcript: c.transcript
} }));

const base = $('Préparer les appels').all();

return $input.all().map((item, i) => {
  const meta = { ...base[i].json };
  delete meta.transcript;
  let a = {};
  try {
    const txt = (item.json.choices && item.json.choices[0] && item.json.choices[0].message && item.json.choices[0].message.content) || '';
    const m = txt.match(/\{[\s\S]*\}/);
    if (m) a = JSON.parse(m[0]);
  } catch (e) {
    a = {};
  }
  const t = a.technique || {};
  const c = a.client || {};
  return { json: {
    ...meta,
    resume: a.resume || 'Analyse indisponible',
    objectif_atteint: t.objectif_atteint === undefined ? null : t.objectif_atteint,
    problemes: t.problemes || [],
    client: {
      motif: c.motif || 'inconnu',
      urgence: c.urgence || 'inconnu',
      ville: c.ville || null,
      questions: c.questions || [],
      valeur_commerciale: c.valeur_commerciale || 'inconnue',
      frein: c.frein || null,
      ressenti: c.ressenti || 'inconnu',
      suite_a_donner: c.suite_a_donner || 'inconnue'
    }
  } };
});

const calls = $input.all().map(i => i.json);
const n = calls.length;

const cnt = (fn) => calls.reduce((acc, c) => {
  const v = fn(c) || 'inconnu';
  acc[v] = (acc[v] || 0) + 1;
  return acc;
}, {});

const problemes = {};
const themes = {};
for (const c of calls) {
  for (const p of (c.problemes || [])) problemes[p.type] = (problemes[p.type] || 0) + 1;
  for (const q of ((c.client && c.client.questions) || [])) themes[q.theme || 'autre'] = (themes[q.theme || 'autre'] || 0) + 1;
}

const stats = {
  nb_appels: n,
  duree_moyenne_s: n ? Math.round(calls.reduce((s, c) => s + (c.duree_s || 0), 0) / n) : 0,
  objectif_atteint: calls.filter(c => c.objectif_atteint === true).length,
  raccroche_par_appelant: calls.filter(c => c.fin === 'user_hangup').length,
  opportunites_fortes: calls.filter(c => c.client && c.client.valeur_commerciale === 'forte').length,
  par_type_appel: cnt(c => c.type_appel),
  par_fin: cnt(c => c.fin),
  par_probleme: problemes,
  par_motif: cnt(c => c.client && c.client.motif),
  par_urgence: cnt(c => c.client && c.client.urgence),
  par_ville: cnt(c => c.client && c.client.ville),
  par_theme_question: themes,
  par_ressenti: cnt(c => c.client && c.client.ressenti),
  par_heure_paris: cnt(c => new Date(c.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', hour12: false }).replace(/\D/g, '') + 'h')
};

return [{ json: { stats, analyses: calls } }];

const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';
let r = { resume: 'Synthèse indisponible.', technique: {}, marketing: {} };
try {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) r = JSON.parse(m[0]);
} catch (e) {}

const s = $('Regrouper').first().json.stats;
const cfg = $('Config').first().json;
const esc = (t) => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const gravite = { 1: 'Mineur', 2: 'Moyen', 3: 'Grave' };
const ul = (arr) => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '';
const t = r.technique || {};
const mk = r.marketing || {};

const forts = ul((t.points_forts || []).map(esc));
const problemes = (t.problemes || []).map(p =>
  '<h3>' + esc(p.titre) + ' <small>(' + (gravite[p.gravite] || '') + ', ' + esc(p.nb_appels) + ' appel(s))</small></h3>' +
  '<p><b>À modifier :</b> ' + esc(p.noeud) + '<br><b>Exemple d\'appel :</b> ' + esc(p.exemple_call_id) + '</p>' +
  '<pre style="background:#f4f4f4;padding:10px;white-space:pre-wrap">' + esc(p.correction_prompt) + '</pre>'
).join('') || '<p>Aucun problème détecté.</p>';

const demandes = ul((mk.demandes_principales || []).map(d => esc(d.motif) + ' : <b>' + esc(d.nb_appels) + '</b>'));
const questions = (mk.questions_frequentes || []).map(q =>
  '<li><b>' + esc(q.question) + '</b> (' + esc(q.nb_appels) + ')<br><i>Réponse suggérée :</i> ' + esc(q.reponse_suggeree) + '</li>'
).join('');
const opportunites = ul((mk.opportunites || []).map(o => esc(o.description) + ' <small>(' + esc(o.call_id) + ')</small>'));
const freins = ul((mk.freins || []).map(esc));
const reco = ul((mk.recommandations || []).map(x => '<b>' + esc(x.action) + '</b> : ' + esc(x.pourquoi)));

const html =
  '<div style="font-family:Arial,sans-serif;max-width:700px">' +
  '<h2>Rapport agent vocal - ' + esc(cfg.nom_client) + '</h2>' +
  '<p>' + esc(r.resume) + '</p>' +
  '<table cellpadding="6" style="border-collapse:collapse;border:1px solid #ddd">' +
  '<tr><td>Appels analysés</td><td><b>' + s.nb_appels + '</b></td></tr>' +
  '<tr><td>Objectif atteint</td><td><b>' + s.objectif_atteint + ' / ' + s.nb_appels + '</b></td></tr>' +
  '<tr><td>Raccroché par l\'appelant</td><td><b>' + s.raccroche_par_appelant + '</b></td></tr>' +
  '<tr><td>Opportunités fortes</td><td><b>' + s.opportunites_fortes + '</b></td></tr>' +
  '<tr><td>Durée moyenne</td><td><b>' + s.duree_moyenne_s + ' s</b></td></tr>' +
  '</table>' +
  '<h2>1. Technique : comportement de l\'assistante</h2>' +
  (forts ? '<h3>Points forts</h3>' + forts : '') +
  '<h3>Problèmes et corrections</h3>' + problemes +
  '<h2>2. Clients et marketing</h2>' +
  (mk.profil_clients ? '<p>' + esc(mk.profil_clients) + '</p>' : '') +
  (demandes ? '<h3>Demandes principales</h3>' + demandes : '') +
  (questions ? '<h3>Questions fréquentes</h3><ul>' + questions + '</ul>' : '') +
  (opportunites ? '<h3>Opportunités à rappeler</h3>' + opportunites : '') +
  (freins ? '<h3>Freins exprimés</h3>' + freins : '') +
  (reco ? '<h3>Recommandations</h3>' + reco : '') +
  '</div>';

return [{ json: {
  subject: 'Rapport hebdo agent vocal - ' + cfg.nom_client + ' - ' + s.nb_appels + ' appels',
  html
} }];
